<template>
  <view class="detail-page">
    <jk-page-nav :title="pageTitle"/>
    <view v-if="detail" class="detail-content">
      <view class="status-hero" :class="detailStatusTone"><jk-icon :name="mode==='order'?'order':'transfer'" size="xl"/><view class="status-main"><text class="status-name">{{detailStatusText}}</text><text class="status-desc">{{statusDescription}}</text></view><image class="status-watermark" src="/static/jk-ui-v2/illustrations/business-hero.png" mode="aspectFit"/></view>

      <view class="card info-card"><view class="info-grid"><view class="info-item"><text>{{businessLabel}}</text><strong>{{no}}</strong></view><view class="info-item"><text>申请时间</text><strong>{{formatTime(detail.createTime||detail.applyTime)}}</strong></view><view class="info-item"><text>申请方</text><strong>{{detail.applicantName||'用户不存在'}}</strong></view><view class="info-item"><text>所属区域</text><strong>{{detail.regionName||detail.applicantRegionName||'-'}}</strong></view><view v-if="mode!=='order'" class="info-item"><text>接收方</text><strong>{{detail.receiverName||detail.targetUserName||detail.parentName||'-'}}</strong></view><view class="info-item full"><text>业务说明</text><strong>{{detail.remark||detail.applyReason||'无'}}</strong></view></view></view>

      <view v-if="showLogistics" class="card logistics-card"><view class="section-head"><text class="section-title">{{mode==='order'?'发货信息':'拨货信息'}}</text><jk-status-tag text="已登记" tone="success"/></view><view class="logistics-row"><text>配送方式</text><strong>{{logisticsCompanyText}}</strong></view><view class="logistics-row"><text>物流单号</text><strong>{{detail.logisticsNo||'-'}}</strong></view><view class="logistics-row"><text>{{mode==='order'?'发货时间':'拨货时间'}}</text><strong>{{formatTime(detail.shippingTime)}}</strong></view></view>

      <view class="card"><view class="section-head"><text class="section-title">商品清单</text><text>共 {{items.length}} 种商品</text></view><jk-product-row v-for="(item,index) in items" :key="item.id||index" :item="item" :fallback="fallbackProduct(index)"><view slot="right" class="product-right"><text>数量</text><strong>{{item.quantity||item.applyQuantity||0}} {{item.unitName||''}}</strong><small v-if="item.totalAmount">¥{{money(item.totalAmount)}}</small></view></jk-product-row><view v-if="detail.totalAmount!==undefined" class="amount-row"><text>订单金额</text><strong>¥{{money(detail.totalAmount)}}</strong></view></view>

      <view class="card timeline-card"><view class="section-title">{{mode==='order'?'订单流程':'调拨流程'}}</view><jk-timeline :steps="timelineSteps"/></view>
      <view v-if="vouchers.length" class="card"><view class="section-head"><text class="section-title">付款凭证</text><text>{{vouchers.length}} 张</text></view><view class="voucher-list"><view v-for="v in vouchers" :key="v.id" class="voucher-item"><image :src="v.voucherUrl" mode="aspectFill" @tap="preview(v.voucherUrl)"/><view><text>{{v.voucherNo||'付款凭证'}}</text><jk-status-tag :text="v.statusText" :tone="v.statusTone"/><small v-if="v.rejectReason">{{v.rejectReason}}</small></view></view></view></view>
      <view class="tip-card"><jk-icon name="info" size="sm"/><text>{{mode==='order'?'付款审核通过并发货后，请及时确认收货入库。':'调拨按申请、审核、付款、拨货、收货流程执行；拨货时必须登记物流信息。'}}</text></view>
    </view>

    <view v-if="detail" class="bottom-actions">
      <template v-if="mode==='handleTransfer'">
        <button v-if="detail.status==='SUBMITTED'" class="outline-danger" @tap="audit(false)">驳回</button><button v-if="detail.status==='SUBMITTED'" class="primary-btn" @tap="audit(true)">审核通过</button>
        <button v-if="detail.status==='PAYMENT_SUBMITTED'" class="outline-danger" @tap="payment(false)">驳回付款</button><button v-if="detail.status==='PAYMENT_SUBMITTED'" class="primary-btn" @tap="payment(true)">确认付款</button>
        <button v-if="detail.status==='PAYMENT_APPROVED'" class="primary-btn full-btn" @tap="openDispatch">确认拨货</button><button v-if="canClose" class="outline-btn" @tap="close">关闭调拨</button>
      </template>
      <template v-else><button class="outline-btn" @tap="contact">联系对方</button><button v-if="canVoucher" class="primary-btn" @tap="goVoucher">上传凭证</button><button v-else-if="canReceive" class="primary-btn" @tap="goReceive">确认收货</button><button v-else-if="canReturn" class="primary-btn" @tap="applyReturn">申请退回</button><button v-else-if="canCancel" class="outline-danger" @tap="cancelBusiness">取消申请</button><button v-else class="primary-btn" @tap="refresh">刷新状态</button></template>
    </view>

    <view v-if="dispatchVisible" class="overlay" @tap="dispatchVisible=false"><view class="sheet" @tap.stop><view class="sheet-head"><text>登记拨货信息</text><text @tap="dispatchVisible=false">关闭</text></view><view class="mode-row"><view :class="{active:dispatchForm.mode==='LOGISTICS'}" @tap="dispatchForm.mode='LOGISTICS'">物流配送</view><view :class="{active:dispatchForm.mode==='SELF_PICKUP'}" @tap="dispatchForm.mode='SELF_PICKUP'">自提/无需物流</view></view><template v-if="dispatchForm.mode==='LOGISTICS'"><view class="form-row"><text>物流公司</text><input v-model.trim="dispatchForm.logisticsCompany" maxlength="100" placeholder="请输入物流公司"/></view><view class="form-row"><text>物流单号</text><input v-model.trim="dispatchForm.logisticsNo" maxlength="100" placeholder="请输入物流单号"/></view></template><view class="form-row"><text>备注</text><input v-model.trim="dispatchForm.remark" maxlength="100" placeholder="选填"/></view><button class="primary-btn submit-dispatch" :disabled="dispatching" @tap="submitDispatch">{{dispatching?'提交中...':'确认拨货'}}</button></view></view>
  </view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkIcon from '@/components/jk/jk-icon.vue';import JkStatusTag from '@/components/jk/jk-status-tag.vue';import JkTimeline from '@/components/jk/jk-timeline.vue';import JkProductRow from '@/components/jk/jk-product-row.vue';
import{getJkPlatformOrderDetail,getJkStockTransferDetail,getJkHandledTransferDetail,auditJkHandledTransfer,confirmJkHandledTransferPayment,confirmJkHandledTransfer,closeJkHandledTransfer,cancelJkPlatformOrder,cancelJkStockTransfer}from'@/api/jk.js';import{jkAuditStatusText,jkBusinessStatusText}from'@/utils/jk-display.js';
export default{components:{JkPageNav,JkIcon,JkStatusTag,JkTimeline,JkProductRow},data(){return{mode:'order',id:0,detail:null,items:[],vouchers:[],auditLogs:[],dispatchVisible:false,dispatching:false,dispatchForm:{mode:'LOGISTICS',logisticsCompany:'',logisticsNo:'',remark:''}}},computed:{pageTitle(){return this.mode==='handleTransfer'?'区县代审核':this.mode==='transfer'?'调拨详情':'订货详情'},businessLabel(){return this.mode==='order'?'订单号':'调拨单号'},no(){return this.mode==='order'?this.detail.platformOrderNo:this.detail.transferNo},canVoucher(){return this.mode!=='handleTransfer'&&['CREATED','AUDIT_APPROVED','PAYMENT_REJECTED'].includes(this.detail.status)},canReceive(){return(this.mode==='order'&&this.detail.status==='SHIPPED')||(this.mode==='transfer'&&this.detail.status==='TRANSFERRED')},canClose(){return['SUBMITTED','AUDIT_APPROVED','PAYMENT_REJECTED'].includes(this.detail.status)},canCancel(){return this.mode!=='handleTransfer'&&((this.mode==='order'&&['CREATED','PAYMENT_REJECTED'].includes(this.detail.status))||(this.mode==='transfer'&&['SUBMITTED','AUDIT_REJECTED','PAYMENT_REJECTED'].includes(this.detail.status)))},canReturn(){return this.mode==='transfer'&&this.detail.status==='STOCK_IN'},detailStatusText(){return this.statusText(this.detail.statusText,this.detail.status)},detailStatusTone(){return this.statusTone(this.detail.status)},showLogistics(){return!!(this.detail.logisticsCompany||this.detail.logisticsNo||this.detail.shippingTime)},logisticsCompanyText(){return this.detail.logisticsCompany==='SELF_PICKUP'?'自提/无需物流':(this.detail.logisticsCompany||'-')},statusDescription(){const m={SUBMITTED:'调拨申请已提交，请耐心等待审核',CREATED:'订单已创建，请尽快完成付款',PAYMENT_SUBMITTED:'付款凭证已提交，等待审核',PAYMENT_APPROVED:'付款已确认，等待发货或拨货',SHIPPED:'订单已发货，请确认收货',TRANSFERRED:'商品已拨出，请确认收货',STOCK_IN:'业务已完成并成功入库',AUDIT_REJECTED:'审核未通过，请查看原因',PAYMENT_REJECTED:'付款凭证审核未通过'};return m[this.detail.status]||'请关注业务处理状态'},timelineSteps(){const s=this.detail.status,o=this.mode==='order',d=o?[['提交订单',['CREATED','PAYMENT_SUBMITTED','PAYMENT_APPROVED','SHIPPED','STOCK_IN']],['付款审核',['PAYMENT_SUBMITTED','PAYMENT_APPROVED','SHIPPED','STOCK_IN']],['备货发货',['SHIPPED','STOCK_IN']],['收货确认',['STOCK_IN']]]:[['提交申请',['SUBMITTED','AUDIT_APPROVED','PAYMENT_SUBMITTED','PAYMENT_APPROVED','TRANSFERRED','STOCK_IN']],['审核',['AUDIT_APPROVED','PAYMENT_SUBMITTED','PAYMENT_APPROVED','TRANSFERRED','STOCK_IN']],['确认付款',['PAYMENT_APPROVED','TRANSFERRED','STOCK_IN']],['确认拨货',['TRANSFERRED','STOCK_IN']],['确认收货',['STOCK_IN']]];return d.map((x,i)=>({title:x[0],done:x[1].includes(s),current:x[1].includes(s)&&(i===d.length-1||!d[i+1][1].includes(s)),danger:['AUDIT_REJECTED','PAYMENT_REJECTED','CLOSED'].includes(s)&&i===1,time:this.timelineTime(i)}))}},onLoad(q){this.mode=q.mode||'order';this.id=Number(q.id);if(!['order','transfer','handleTransfer'].includes(this.mode))return this.$util.Tips({title:'无效业务类型'});this.load()},onShow(){if(this.id)this.load()},methods:{load(){const f=this.mode==='handleTransfer'?getJkHandledTransferDetail:(this.mode==='transfer'?getJkStockTransferDetail:getJkPlatformOrderDetail);f(this.id).then(r=>{const p=r.data||r||{};this.detail=this.mode==='order'?(p.order||p):(p.transfer||p);this.items=p.items||this.detail.items||[];this.vouchers=(p.vouchers||[]).map(v=>Object.assign({},v,{statusText:this.auditStatusText(v.voucherStatusText||v.auditStatusText,v.auditStatus),statusTone:this.statusTone(v.auditStatus)}));this.auditLogs=p.auditLogs||[]}).catch(e=>this.$util.Tips({title:e||'详情加载失败'}))},statusText(t,s){return t||jkBusinessStatusText(s)},auditStatusText(t,s){return t||jkAuditStatusText(s)},statusTone(s){if(['STOCK_IN','COMPLETED','AUDIT_APPROVED','PAYMENT_APPROVED','TRANSFERRED'].includes(s))return'success';if(['AUDIT_REJECTED','PAYMENT_REJECTED','CLOSED','CANCELLED','REJECTED'].includes(s))return'danger';if(s==='SHIPPED')return'info';return'warning'},timelineTime(i){const l=this.auditLogs[i],b=i===0?(this.detail.createTime||this.detail.applyTime):(l&&l.createTime);return b?String(b).replace('T',' ').slice(5,16):''},formatTime(v){return v?String(v).replace('T',' ').slice(0,19):'-'},money(v){const n=Number(v||0);return Number.isNaN(n)?String(v||'0.00'):n.toFixed(2)},fallbackProduct(i){return['/static/jk-ui-v2/products/meter.png','/static/jk-ui-v2/products/glucose-paper.png','/static/jk-ui-v2/products/needle.png','/static/jk-ui-v2/products/wipes.png'][i%4]},goVoucher(){uni.navigateTo({url:'/pages/jk/trade/voucher?mode='+this.mode+'&id='+this.id})},goReceive(){uni.navigateTo({url:'/pages/jk/trade/receive?mode='+this.mode+'&id='+this.id})},audit(a){const x=()=>auditJkHandledTransfer({businessId:this.id,approved:a,remark:a?'APP审核通过':'APP审核驳回'}).then(()=>this.load());if(a)return x();uni.showModal({title:'驳回调拨',editable:true,placeholderText:'请输入驳回原因',success:r=>{if(r.confirm)auditJkHandledTransfer({businessId:this.id,approved:false,remark:r.content||'APP审核驳回'}).then(()=>this.load())}})},payment(a){confirmJkHandledTransferPayment({businessId:this.id,approved:a,remark:a?'APP确认付款':'APP驳回付款'}).then(()=>this.load())},openDispatch(){this.dispatchForm={mode:'LOGISTICS',logisticsCompany:'',logisticsNo:'',remark:''};this.dispatchVisible=true},submitDispatch(){if(this.dispatchForm.mode==='LOGISTICS'&&(!this.dispatchForm.logisticsCompany||!this.dispatchForm.logisticsNo))return this.$util.Tips({title:'请填写物流公司和物流单号'});const self=this.dispatchForm.mode==='SELF_PICKUP';this.dispatching=true;confirmJkHandledTransfer({businessId:this.id,logisticsCompany:self?'SELF_PICKUP':this.dispatchForm.logisticsCompany,logisticsNo:self?'SELF_PICKUP':this.dispatchForm.logisticsNo,remark:this.dispatchForm.remark||(self?'APP自提拨货':'APP物流拨货')}).then(()=>{this.dispatchVisible=false;this.load()}).catch(e=>this.$util.Tips({title:e||'拨货失败'})).finally(()=>this.dispatching=false)},close(){closeJkHandledTransfer({businessId:this.id,remark:'APP关闭调拨'}).then(()=>this.load())},cancelBusiness(){uni.showModal({title:'取消申请',editable:true,placeholderText:'请输入取消原因',success:r=>{if(r.confirm)(this.mode==='order'?cancelJkPlatformOrder:cancelJkStockTransfer)(this.id,{businessId:this.id,remark:r.content||'申请人主动取消'}).then(()=>this.load())}})},applyReturn(){uni.navigateTo({url:'/pages/jk/return/create?transferId='+this.id})},preview(u){uni.previewImage({urls:[u],current:u})},contact(){uni.showToast({title:'请通过平台客服或绑定手机号联系',icon:'none'})},refresh(){this.load()}}};
</script>
<style scoped>.detail-page{min-height:100vh;padding-bottom:128rpx;background:#f7f9f9}.detail-content{padding:16rpx 22rpx 32rpx}.status-hero{position:relative;display:flex;align-items:center;min-height:140rpx;overflow:hidden;padding:22rpx;border-radius:20rpx;background:linear-gradient(135deg,#20c39c,#61d4b6);color:#fff}.status-hero.danger{background:linear-gradient(135deg,#ff7a6e,#ff9a85)}.status-hero.info{background:linear-gradient(135deg,#4ca5ee,#76bdf5)}.status-main{z-index:2;display:flex;flex-direction:column;gap:10rpx;margin-left:14rpx}.status-name{font-size:32rpx;font-weight:700}.status-desc{font-size:21rpx;opacity:.9}.status-watermark{position:absolute;right:-55rpx;bottom:-100rpx;width:250rpx;height:250rpx;opacity:.13}.card{margin-top:18rpx;padding:22rpx;border-radius:20rpx;background:#fff}.info-grid{display:flex;flex-wrap:wrap}.info-item{display:flex;width:50%;min-height:68rpx;flex-direction:column;gap:6rpx;box-sizing:border-box}.info-item.full{width:100%}.info-item text,.logistics-row text{color:#78858c;font-size:20rpx}.info-item strong,.logistics-row strong{color:#273239;font-size:21rpx;font-weight:500}.section-head,.logistics-row,.amount-row{display:flex;align-items:center;justify-content:space-between}.section-title{color:#1f2937;font-size:27rpx;font-weight:700}.product-right{display:flex;flex-direction:column;align-items:flex-end;gap:5rpx}.product-right text,.product-right small{color:#879299;font-size:18rpx}.product-right strong{color:#202b31;font-size:23rpx}.amount-row{padding-top:18rpx;border-top:1rpx solid #edf1f0}.amount-row strong{color:#ef6548;font-size:28rpx}.logistics-row{min-height:64rpx;border-bottom:1rpx solid #edf1f0}.voucher-item{display:flex;align-items:center;gap:14rpx;padding:12rpx 0}.voucher-item image{width:100rpx;height:100rpx;border-radius:12rpx}.voucher-item>view{display:flex;flex-direction:column;gap:6rpx}.tip-card{display:flex;align-items:center;gap:10rpx;margin-top:18rpx;padding:18rpx;border-radius:15rpx;background:#eef8f5;color:#63736d;font-size:20rpx}.bottom-actions{position:fixed;z-index:50;right:0;bottom:0;left:0;display:flex;gap:12rpx;padding:14rpx 22rpx calc(16rpx + env(safe-area-inset-bottom));background:#fff}.bottom-actions button{flex:1;height:76rpx;margin:0;border-radius:38rpx;font-size:23rpx;line-height:76rpx}.bottom-actions button::after{border:0}.primary-btn{background:#10b981!important;color:#fff!important}.outline-btn{border:2rpx solid #10b981!important;background:#fff!important;color:#10a981!important}.outline-danger{border:2rpx solid #ef6a58!important;background:#fff!important;color:#ef5b4c!important}.overlay{position:fixed;z-index:100;top:0;right:0;bottom:0;left:0;background:rgba(20,32,29,.42)}.sheet{position:absolute;right:0;bottom:0;left:0;padding:24rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.sheet-head{display:flex;justify-content:space-between;margin-bottom:20rpx}.sheet-head text:first-child{font-size:29rpx;font-weight:700}.sheet-head text:last-child{color:#7d898f;font-size:22rpx}.mode-row{display:flex;gap:12rpx}.mode-row view{flex:1;padding:18rpx;border:1rpx solid #dce7e4;border-radius:14rpx;text-align:center;font-size:22rpx}.mode-row view.active{border-color:#10b981;background:#eafaf6;color:#10a981}.form-row{display:flex;align-items:center;min-height:82rpx;border-bottom:1rpx solid #edf1f0}.form-row text{width:130rpx;color:#66747a;font-size:22rpx}.form-row input{flex:1;text-align:right;font-size:22rpx}.submit-dispatch{width:100%;height:78rpx;margin-top:22rpx;border-radius:39rpx;line-height:78rpx}</style>
